'use strict';
const $=id=>document.getElementById(id), KEY='uav-collab-v1';let data={records:[]};const conditions={action:'行动侧重',reason:'理由侧重',projection:'预测侧重'};
function read(){try{data=JSON.parse(localStorage.getItem(KEY)||'{"records":[]}');if(!Array.isArray(data.records))throw Error('格式不匹配');$('adminStatus').textContent='已读取本浏览器记录 · '+new Date().toLocaleTimeString('zh-CN')}catch(e){$('adminStatus').textContent='无法读取本地记录：'+e.message;return}const selected=$('sessionFilter').value,ids=[...new Set(data.records.map(r=>r.sessionId))];$('sessionFilter').replaceChildren(new Option('全部会话','all'));ids.forEach(id=>{const latest=data.records.filter(r=>r.sessionId===id).at(-1);$('sessionFilter').add(new Option(`${latest.participant} / ${id.slice(0,8)}`,id))});$('sessionFilter').value=ids.includes(selected)?selected:'all';$('metricSessions').textContent=ids.length;$('metricEvents').textContent=data.records.length;$('metricDecisions').textContent=data.records.filter(r=>['accept','reject','modify_apply'].includes(r.type)).length;$('metricNode').textContent=data.node||'—';render()}
function filtered(){return data.records.filter(r=>$('sessionFilter').value==='all'||r.sessionId===$('sessionFilter').value)}
function render(){$('adminRows').replaceChildren();const rows=filtered();if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=7;td.textContent='暂无记录。请先在操作者界面完成一轮模拟。';tr.append(td);$('adminRows').append(tr)}rows.slice(-500).reverse().forEach(r=>{const tr=document.createElement('tr');[new Date(r.timestamp).toLocaleString('zh-CN',{hour12:false}),`${r.participant} / ${r.sessionId.slice(0,8)}`,r.node+(r.obstacleSubtype==='dynamic'?' / 动态':r.obstacleSubtype==='static'?' / 静态':''),conditions[r.condition]||r.condition,r.label,r.detail,r.reactionMs==null?'—':(r.reactionMs/1000).toFixed(2)+' s'].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td)});$('adminRows').append(tr)});if(rows.length>500)$('adminStatus').textContent+=' · 页面显示最近 500 条，导出包含全部筛选结果'}
function csvCell(v){let text=typeof v==='object'&&v!==null?JSON.stringify(v):String(v??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}
function download(format){const records=filtered(),cols=['id','version','timestamp','sessionId','participant','condition','trialId','node','obstacleSubtype','destination','goalDeferred','type','label','detail','reactionMs','before','after','stimulus','rationale'];const text=format==='json'?JSON.stringify({schemaVersion:'2.0.0',exportedAt:new Date().toISOString(),mode:'preset-simulation',timing:'reactionMs 是自情境呈现起的墙钟毫秒，包含离开页面时间',records},null,2):'\uFEFF'+cols.join(',')+'\r\n'+records.map(r=>cols.map(k=>csvCell(r[k])).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:format==='json'?'application/json':'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`uav-research-${new Date().toISOString().slice(0,10)}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);$('adminStatus').textContent=`已导出 ${records.length} 条记录`}
$('saveConfig').onclick=()=>{const participant=$('adminParticipant').value.trim();if(!participant){$('configStatus').textContent='请填写研究编号';return}try{localStorage.setItem('uav-research-config-v1',JSON.stringify({participant,condition:$('adminCondition').value,node:$('adminNode').value,subtype:$('adminSubtype').value,nonce:crypto.randomUUID(),savedAt:new Date().toISOString()}));$('configStatus').textContent='已保存。前台下一次规划路线时生效，进行中任务保持原条件。'}catch(e){$('configStatus').textContent='保存失败，请检查浏览器存储设置'}};$('refresh').onclick=read;$('sessionFilter').onchange=render;$('adminCsv').onclick=()=>download('csv');$('adminJson').onclick=()=>download('json');window.addEventListener('storage',e=>{if(e.key===KEY)read()});try{const config=JSON.parse(localStorage.getItem('uav-research-config-v1')||'null');if(config){$('adminParticipant').value=config.participant;$('adminCondition').value=config.condition;$('adminNode').value=['N1','N2','N34','N5'].includes(config.node)?config.node:'N1';$('adminSubtype').value=config.subtype==='dynamic'?'dynamic':'static'}}catch(e){}read();

$('adminNode').onchange=()=>{$('subtypeLabel').hidden=$('adminNode').value!=='N34'};$('adminNode').onchange();
